WITH session_summary AS (SELECT session_id, COUNT(CASE WHEN page = '/cart' THEN 1 END) AS cart_count, COUNT(*) AS web_event_count FROM web_events GROUP BY session_id) SELECT sessions.id, sessions.browser, sessions.customer_id, session_summary.cart_count, session_summary.web_event_count FROM sessions LEFT JOIN session_summary ON sessions.id = session_summary.session_id ORDER BY sessions.browser
